var CODE="1234"; // ganti sesuai jawaban teka-teki
const $=id=>document.getElementById(id);
const lock=$("lock"),pass=$("pass"),dotsEl=$("dots"),msg=$("msg"),pad=$("pad"),wall=$("wall"),island=$("island"),root=document.documentElement,phone=$("phone");
let entry="",tries=0,startY=null,dy=0;
const wi=wall.querySelector("img"),bi=wi.cloneNode();bi.className="b";wall.appendChild(bi);
const setBlur=p=>{bi.style.opacity=Math.max(0,Math.min(1,p))};
if(wi.decode)wi.decode().catch(()=>{});
let passT=0;
// Respon instan: aksi jalan saat jari menyentuh (pointerdown), bukan menunggu klik. Klik dari keyboard tetap jalan.
function tapOn(el,fn){
  el.addEventListener("pointerdown",e=>{e.preventDefault();fn()});
  el.addEventListener("click",e=>{if(e.detail===0)fn()});
}
const letters={2:"ABC",3:"DEF",4:"GHI",5:"JKL",6:"MNO",7:"PQRS",8:"TUV",9:"WXYZ"};
[1,2,3,4,5,6,7,8,9,"",0,"Batal"].forEach(v=>{
  if(v===""){pad.appendChild(document.createElement("span"));return}
  const b=document.createElement("button");
  if(v==="Batal"){b.className="k t";b.textContent="Batal";tapOn(b,closePass)}
  else{b.className="k";b.innerHTML=v+"<small>"+(letters[v]||"&nbsp;")+"</small>";tapOn(b,()=>press(String(v)))}
  pad.appendChild(b);
});
const draw=()=>[...dotsEl.children].forEach((d,i)=>d.classList.toggle("f",i<entry.length));
function openPass(){
  clearTimeout(passT);pass.hidden=false;pass.style.pointerEvents="";
  pass.style.transition="opacity .32s ease";pass.style.opacity=1;
  lock.classList.remove("drag");wall.classList.remove("live");lock.style.transform="";lock.classList.add("gone");setBlur(1);
}
function closePass(){
  entry="";draw();msg.textContent="";
  clearTimeout(passT);pass.style.pointerEvents="none";
  pass.style.transition="opacity .26s ease";pass.style.opacity=0;   // keypad memudar dulu, tidak menimpa wallpaper
  setBlur(0);
  requestAnimationFrame(()=>lock.classList.remove("gone"));          // lalu layar kunci turun halus
  passT=setTimeout(()=>{if(!lock.classList.contains("gone"))pass.hidden=true},340);
}
function press(d){
  if(entry.length>=4)return;entry+=d;draw();
  if(entry.length<4)return;
  setTimeout(()=>{
    if(entry===currentCode()){
      const hm=$("home");hm.style.opacity=0;hm.hidden=false;pass.style.pointerEvents="none";
      requestAnimationFrame(()=>requestAnimationFrame(()=>{hm.style.opacity=1;pass.style.transition="opacity .55s ease";pass.style.opacity=0}));
      setTimeout(()=>{pass.hidden=true;hm.style.opacity="";pass.style.pointerEvents=""},650)}
    else{tries++;dotsEl.classList.remove("shake");void dotsEl.offsetWidth;dotsEl.classList.add("shake");
      if(navigator.vibrate)navigator.vibrate(200);
      msg.textContent=tries>=3?WRONG_HINT:"Kode salah. Coba lagi.";entry="";draw()}
  },180);
}
lock.addEventListener("pointerdown",e=>{clearTimeout(passT);pass.style.pointerEvents="none";startY=e.clientY;dy=0;lock.classList.add("drag");wall.classList.add("live");lock.setPointerCapture(e.pointerId);pass.style.transition="none";pass.style.opacity=0;pass.hidden=false});
let raf=0;
lock.addEventListener("pointermove",e=>{if(startY===null)return;dy=Math.min(0,e.clientY-startY);if(raf)return;raf=requestAnimationFrame(()=>{raf=0;lock.style.transform="translate3d(0,"+dy+"px,0)";lock.style.opacity=1+dy/400;pass.style.opacity=Math.min(1,-dy/140);setBlur(-dy/130)})});
function end(){
  if(startY===null)return;cancelAnimationFrame(raf);raf=0;const m=dy;startY=null;lock.classList.remove("drag");wall.classList.remove("live");lock.style.opacity="";
  if(m<-110)openPass();
  else{lock.style.transform="";pass.style.transition="opacity .3s ease";pass.style.opacity=0;setBlur(0);clearTimeout(passT);passT=setTimeout(()=>{if(!lock.classList.contains("gone"))pass.hidden=true},360)}
}
lock.addEventListener("pointerup",end);lock.addEventListener("pointercancel",end);
document.addEventListener("keydown",e=>{
  if(!pass.hidden&&/^\d$/.test(e.key))press(e.key);
  else if(pass.hidden&&(e.key==="ArrowUp"||e.key===" ")){pass.hidden=false;openPass()}
});

// ===== Chat Kontak =====
const chat=$("chat"),msgs=$("msgs"),tray=$("tray"),st=$("st");
let started=false,wrong=0;
const wait=ms=>new Promise(r=>setTimeout(r,ms));
const nodes={};
function bub(t,me){const d=document.createElement("div");d.className="m "+(me?"me":"th");d.textContent=t;msgs.appendChild(d);msgs.scrollTop=msgs.scrollHeight}
async function say(t){st.textContent="mengetik…";await wait(700+t.length*22);st.textContent="online";bub(t,false);await wait(300)}
async function play(id){
  const n=nodes[id];tray.innerHTML="";
  for(const t of n.msgs){if(t==="!"){scare();await wait(3800)}else if(t[0]==="@"){sfx(t.slice(1));await wait(900)}else if(t[0]===">"){await wait(800);bub(t.slice(1),true)}else await say(t)}
  if(n.choices)n.choices.forEach(([label,to])=>{const b=document.createElement("button");b.className="c";b.textContent=label;b.onclick=()=>{bub(label,true);play(to)};tray.appendChild(b)});
  else if(n.input)showInput(n);
  else if(n.tip){const e=document.createElement("div");e.className="end";e.textContent=n.tip;tray.appendChild(e)}
  else if(n.next)play(n.next);
  else if(n.fin){const e=document.createElement("div");e.className="end";e.textContent=END_TEXT;tray.appendChild(e)}
  else if(n.end){const e=document.createElement("div");e.className="end";e.textContent="Bersambung…";tray.appendChild(e);const g=document.createElement("button");g.className="opg";g.textContent="📷 Buka Galeri";g.onclick=openGal;tray.appendChild(g)}
}
function showInput(n){
  tray.innerHTML='<div class="row"><input id="ans" placeholder="Ketik jawaban gembok…" autocomplete="off"><button class="send" id="sendBtn">Kirim</button></div>';
  const a=$("ans"),go=async()=>{
    const v=a.value.trim().toLowerCase();if(!v)return;
    bub(a.value.trim(),true);tray.innerHTML="";
    if(n.input.answer.includes(v))play(n.input.ok);
    else{wrong++;await say(n.input.hint||(wrong>=2?"coba pikir yang selalu ngikutin kita pas ngaca":"hmm kayaknya bukan deh. coba lagi"));showInput(n)}
  };
  $("sendBtn").onclick=go;a.onkeydown=e=>{if(e.key==="Enter")go()};
}

// ===== Bab 2: Galeri =====
var PH=[];
const gal=$("gal"),grid=$("grid"),gv=$("gv"),seen=new Set();
function renderGrid(){
  grid.innerHTML="";
  PH.forEach((p,i)=>{
    const b=document.createElement("button"),locked=i===PH.length-1&&seen.size<PH.length-1;
    b.className="gt"+(seen.has(i)?" seen":"")+(locked?" lk":"");
    b.style.background=p[3];b.innerHTML=p[2]+"<small>"+p[0]+"</small>";
    b.onclick=()=>{if(locked){if(navigator.vibrate)navigator.vibrate(60);return}openPh(i)};
    grid.appendChild(b);
  });
}
function openPh(i){
  const p=PH[i];seen.add(i);
  gv.style.background=p[3];gv.hidden=false;
  gv.innerHTML='<div class="big">'+p[2]+'</div><h3>'+p[1]+' · '+p[0]+'</h3><p>'+p[4]+'</p><button id="gclose">Tutup</button>';
  $("gclose").onclick=()=>{gv.hidden=true;renderGrid();if(seen.size===PH.length)finishGal()};
}
function finishGal(){
  if($("gendbox").firstChild)return;
  const d=document.createElement("div");d.className="gend";
  d.innerHTML=GAL_END;
  $("gendbox").appendChild(d);if(navigator.vibrate)navigator.vibrate([80,40,80]);
}
function openGal(){chat.hidden=true;gal.hidden=false;renderGrid()}
$("gback").onclick=()=>{gal.hidden=true};

// ===== Bab 3-5: teka-teki aplikasi, jumpscare, tamat =====
function scare(face){
  try{const t=actx.currentTime,n=actx.createBufferSource(),b=actx.createBuffer(1,actx.sampleRate*.7,actx.sampleRate),d=b.getChannelData(0);
    for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);
    const g=actx.createGain();g.gain.value=.9;n.buffer=b;n.connect(g);g.connect(actx.destination);n.start(t);
    const o=actx.createOscillator();o.type="sawtooth";o.frequency.setValueAtTime(900,t);o.frequency.exponentialRampToValueAtTime(70,t+.6);
    const g2=actx.createGain();g2.gain.value=.5;o.connect(g2);g2.connect(actx.destination);o.start(t);o.stop(t+.7)}catch(e){}
  if(navigator.vibrate)navigator.vibrate([300,50,300]);
  const d=document.createElement("div");d.className="scare";d.textContent=face||"👹";phone.appendChild(d);setTimeout(()=>d.remove(),950);
}
const av2=$("av2");
const APPV={};
function openAv(k){
  const a=APPV[k];av2.hidden=false;
  const head='<button class="bk" id="avb">‹ Beranda</button><h2>'+a.t+'</h2>';
  const show=()=>{
    av2.innerHTML=head+"<p>"+a.body+"</p>"+(a.door?'<div class="row"><input id="avi" inputmode="numeric" maxlength="4" placeholder="Kode pintu"><button class="go" id="avg">Buka</button></div><div class="er" id="ave"></div>':"");
    $("avb").onclick=()=>av2.hidden=true;
    if(a.door)$("avg").onclick=()=>{
      if($("avi").value.trim()===a.door){av2.hidden=true;scare();setTimeout(()=>{chat.hidden=false;play(DOOR_NEXT)},3700)}
      else{$("ave").textContent="Pintu tidak bergerak.";if(navigator.vibrate)navigator.vibrate(120)}};
  };
  if(a.lock&&!a.ok){
    av2.innerHTML=head+'<p>🔒 '+a.lock.hint+'</p><div class="row"><input id="avi" placeholder="Kata sandi"><button class="go" id="avg">Buka</button></div><div class="er" id="ave"></div>';
    $("avb").onclick=()=>av2.hidden=true;
    $("avg").onclick=()=>{if(a.lock.a.includes($("avi").value.trim().toLowerCase())){a.ok=1;show()}else $("ave").textContent="Salah."};
  }else show();
}










// ===== Audio horor: backsound, sfx, tawa kuntilanak, wajah hantu =====
function noiseBuf(d){const b=actx.createBuffer(1,actx.sampleRate*d,actx.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;return b}
function burst(t,d,type,freq,vol){const n=actx.createBufferSource(),f=actx.createBiquadFilter(),g=actx.createGain();n.buffer=noiseBuf(d);f.type=type;f.frequency.value=freq;g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.001,t+d);n.connect(f);f.connect(g);g.connect(actx.destination);n.start(t)}
function laugh(){
  const t0=actx.currentTime+.05;
  for(let i=0;i<8;i++){
    const t=t0+i*.27,o=actx.createOscillator(),f=actx.createBiquadFilter(),g=actx.createGain(),v=actx.createOscillator(),vg=actx.createGain();
    const base=640+Math.min(i,3)*70-(i>4?(i-4)*80:0);
    o.type="sawtooth";o.frequency.setValueAtTime(base,t);o.frequency.exponentialRampToValueAtTime(base*1.5,t+.1);o.frequency.exponentialRampToValueAtTime(base*.75,t+.24);
    v.frequency.value=32;vg.gain.value=45;v.connect(vg);vg.connect(o.frequency);
    f.type="bandpass";f.frequency.value=1600;f.Q.value=4;
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(i===7?.45:.32,t+.03);g.gain.exponentialRampToValueAtTime(.001,t+(i===7?.7:.24));
    o.connect(f);f.connect(g);g.connect(actx.destination);o.start(t);v.start(t);o.stop(t+.75);v.stop(t+.75);
  }
}
function sfx(k){try{
  const t=actx.currentTime+.02;
  if(k==="knock"){[0,.3,.6].forEach(d=>{burst(t+d,.18,"lowpass",220,1.2)});if(navigator.vibrate)navigator.vibrate([60,200,60,200,60])}
  else if(k==="creak"){const o=actx.createOscillator(),f=actx.createBiquadFilter(),g=actx.createGain();o.type="sawtooth";o.frequency.setValueAtTime(140,t);o.frequency.linearRampToValueAtTime(70,t+1.2);f.type="bandpass";f.frequency.value=500;f.Q.value=6;g.gain.setValueAtTime(.18,t);g.gain.linearRampToValueAtTime(0,t+1.3);o.connect(f);f.connect(g);g.connect(actx.destination);o.start(t);o.stop(t+1.3);burst(t+1.2,.2,"lowpass",300,.9)}
  else if(k==="glass"){for(let i=0;i<14;i++)burst(t+Math.random()*.7,.15,"highpass",3000+Math.random()*3000,.5);burst(t,.3,"lowpass",600,1)}
  else if(k==="laugh")laugh();
}catch(e){}}
function startBgm(){
  const m=actx.createGain();m.gain.value=.07;m.connect(actx.destination);
  [55,58.3,82].forEach(fr=>{const o=actx.createOscillator();o.type="sine";o.frequency.value=fr;o.connect(m);o.start()});
  const n=actx.createBufferSource(),f=actx.createBiquadFilter(),g=actx.createGain(),l=actx.createOscillator(),lg=actx.createGain();
  n.buffer=noiseBuf(4);n.loop=true;f.type="bandpass";f.frequency.value=420;f.Q.value=.8;g.gain.value=.035;
  l.frequency.value=.12;lg.gain.value=.03;l.connect(lg);lg.connect(g.gain);l.start();
  n.connect(f);f.connect(g);g.connect(actx.destination);n.start();
  (function rnd(){setTimeout(()=>{try{
    const t=actx.currentTime,r=Math.random();
    if(r<.4){const o=actx.createOscillator(),gg=actx.createGain();o.type="sine";o.frequency.value=1800;gg.gain.setValueAtTime(.05,t);gg.gain.exponentialRampToValueAtTime(.001,t+.25);o.connect(gg);gg.connect(actx.destination);o.start(t);o.stop(t+.3)}
    else if(r<.75){const o=actx.createOscillator(),ff=actx.createBiquadFilter(),gg=actx.createGain();o.type="sawtooth";o.frequency.setValueAtTime(110,t);o.frequency.linearRampToValueAtTime(65,t+1);ff.type="bandpass";ff.frequency.value=450;ff.Q.value=6;gg.gain.setValueAtTime(.05,t);gg.gain.linearRampToValueAtTime(0,t+1.1);o.connect(ff);ff.connect(gg);gg.connect(actx.destination);o.start(t);o.stop(t+1.1)}
    else{[0,.45].forEach(d=>burst(t+d,.2,"lowpass",90,.5))}
  }catch(e){}rnd()},7000+Math.random()*8000)})();
}
