const SFXB64="";let sfxBuf=null;
function loadSfx(){try{const bin=atob(SFXB64),u=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);actx.decodeAudioData(u.buffer,b=>{sfxBuf=b},()=>{})}catch(e){}}
function laugh(){
  const t0=actx.currentTime+.02,mg=actx.createGain(),cp=actx.createDynamicsCompressor();mg.gain.value=1.7;mg.connect(cp);cp.connect(actx.destination);
  for(let i=0;i<11;i++){
    const t=t0+i*.25,base=1000+Math.min(i,4)*90-(i>6?(i-6)*70:0),last=i===10,dur=last?.9:.24;
    const f=actx.createBiquadFilter(),g=actx.createGain(),v=actx.createOscillator(),vg=actx.createGain();
    f.type="bandpass";f.frequency.value=2200;f.Q.value=3;
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.55,t+.025);g.gain.exponentialRampToValueAtTime(.001,t+dur);
    v.frequency.value=38;vg.gain.value=70;v.connect(vg);v.start(t);v.stop(t+dur+.05);
    [1,1.012].forEach(m=>{const o=actx.createOscillator();o.type="sawtooth";
      o.frequency.setValueAtTime(base*m,t);o.frequency.exponentialRampToValueAtTime(base*1.6*m,t+.09);o.frequency.exponentialRampToValueAtTime(base*.7*m,t+dur);
      vg.connect(o.frequency);o.connect(f);o.start(t);o.stop(t+dur+.05)});
    f.connect(g);g.connect(mg);
  }
}
