// ===== Layar mati -> nyala, notifikasi masuk satu per satu dengan bunyi =====
const sleepEl=$("sleep");let actx;
const nbox=document.querySelector(".notifs"),notes=[...nbox.querySelectorAll(".n")];notes.forEach(n=>n.remove());
function ping(){
  try{
    const t=actx.currentTime;
    [[1318.5,0],[1568,.11]].forEach(([f,d])=>{
      const o=actx.createOscillator(),g=actx.createGain();
      o.type="sine";o.frequency.value=f;
      g.gain.setValueAtTime(0,t+d);g.gain.linearRampToValueAtTime(.25,t+d+.01);g.gain.exponentialRampToValueAtTime(.001,t+d+.7);
      o.connect(g);g.connect(actx.destination);o.start(t+d);o.stop(t+d+.75);
    });
  }catch(e){}
  if(navigator.vibrate)navigator.vibrate([40,40,40]);
}
var DISCLAIMER_TITLE="",DISCLAIMER=[],DISCLAIMER_BTN="Lanjutkan";
function wake(){
  sleepEl.classList.add("off");setTimeout(()=>sleepEl.remove(),1600);
  notes.slice().reverse().forEach((n,i)=>setTimeout(()=>{
    const w=document.createElement("div"),x=document.createElement("div");
    w.className="nw";x.className="nx";x.appendChild(n);w.appendChild(x);nbox.prepend(w);
    requestAnimationFrame(()=>requestAnimationFrame(()=>w.classList.add("show")));ping();
  },1100+i*1500));
  setTimeout(startSpam,8500);
}
var INTRO_FADE=3,INTRO_GAP=2000,INTRO_FPS=15,INTRO_FRAMES=[],INTRO_AUDIO="",introImgs=[],introBuf=null,introDone=false;
// ===== Backsound loop dari mp4: fade-in saat gambar headset hilang, berulang terus =====
var BACKSOUND="",BACKSOUND_VOL=.6,BACKSOUND_FADE=4,bsBuf=null,bsStarted=false,bsWant=false,bsSrc=null,bsGain=null,BACKSOUND_OUT=3;
function prepareBacksound(){
  if(!BACKSOUND||bsBuf)return;
  try{
    if(!actx)actx=new (window.AudioContext||window.webkitAudioContext)();
    const bin=atob(BACKSOUND.split(",")[1]),u=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
    actx.decodeAudioData(u.buffer,b=>{bsBuf=b;if(bsWant)startBacksound()},()=>{});
  }catch(e){}
}
function startBacksound(){
  if(!BACKSOUND||bsStarted)return;
  bsWant=true;
  if(!bsBuf||!actx)return;                       // belum selesai di-decode: otomatis mulai begitu siap
  bsStarted=true;
  try{
    actx.resume();
    const src=actx.createBufferSource(),gn=actx.createGain(),t=actx.currentTime;
    src.buffer=bsBuf;src.loop=true;                // durasi kurang -> audio diulang
    gn.gain.setValueAtTime(0,t);gn.gain.linearRampToValueAtTime(BACKSOUND_VOL,t+BACKSOUND_FADE);
    src.connect(gn);gn.connect(actx.destination);src.start(t);bsSrc=src;bsGain=gn;
  }catch(e){}
}
function stopBacksound(){                       // fade-out lalu berhenti (dipanggil saat tombol Mulai ditekan)
  bsWant=false;
  if(!bsSrc||!bsGain)return;
  try{
    const t=actx.currentTime,g=bsGain.gain,s=bsSrc;
    g.cancelScheduledValues(t);g.setValueAtTime(g.value,t);g.linearRampToValueAtTime(0,t+BACKSOUND_OUT);
    s.stop(t+BACKSOUND_OUT+.1);
  }catch(e){}
  bsSrc=null;bsGain=null;
}
function prepareIntro(){
  prepareBacksound();
  if(!INTRO_FRAMES.length)return;
  introImgs=INTRO_FRAMES.map(src=>{const i=new Image();i.src=src;if(i.decode)i.decode().catch(()=>{});return i});
  try{
    if(!actx)actx=new (window.AudioContext||window.webkitAudioContext)();   // dibuat dulu (masih diam), dinyalakan saat ketukan pertama
    if(INTRO_AUDIO){
      const bin=atob(INTRO_AUDIO.split(",")[1]),u=new Uint8Array(bin.length);
      for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
      actx.decodeAudioData(u.buffer,b=>{introBuf=b},()=>{});
    }
  }catch(e){}
}
function playIntro(){
  sleepEl.classList.add("intro");sleepEl.innerHTML="";
  const cv=document.createElement("canvas");cv.className="intro-v";
  const n=introImgs.length,w=introImgs[0].naturalWidth||420;cv.width=cv.height=w;
  sleepEl.appendChild(cv);const g=cv.getContext("2d");
  const finish=()=>{
    if(introDone)return;introDone=true;
    cv.classList.remove("on");cv.classList.add("out");
    startBacksound();                               // fade-in backsound begitu gambar headset hilang
    setTimeout(()=>{try{cv.remove()}catch(e){}},700);
    setTimeout(showDisclaimer,700+INTRO_GAP);       // jeda sebelum disclaimer
  };
  let t0=0,last=-1;
  const loop=()=>{
    const el=(performance.now()-t0)/1000,idx=Math.min(n-1,Math.floor(el*INTRO_FPS));
    if(idx!==last){const im=introImgs[idx];if(im&&im.complete)g.drawImage(im,0,0,w,w);last=idx}
    if(el>=n/INTRO_FPS+.15)finish();else requestAnimationFrame(loop);
  };
  const go=()=>{
    t0=performance.now();
    if(introBuf&&actx){try{const src=actx.createBufferSource(),gn=actx.createGain(),tt=actx.currentTime;src.buffer=introBuf;gn.gain.setValueAtTime(0,tt);gn.gain.linearRampToValueAtTime(1,tt+INTRO_FADE);src.connect(gn);gn.connect(actx.destination);src.start()}catch(e){}}
    requestAnimationFrame(()=>requestAnimationFrame(()=>cv.classList.add("on")));requestAnimationFrame(loop);
  };
  const first=introImgs[0];
  if(first.complete)go();else{first.onload=go;first.onerror=()=>{introDone=true;showDisclaimer()};setTimeout(()=>{if(!t0)go()},3000)}
}

// ===== Prolog: teks mengetik per paragraf, tombol Next, lalu fade ke HP =====
var KEY_VOL=.32,kbNoise=null;
// Sampel suara keyboard (diambil dari video referensi): tuts biasa + spasi
const KEYSFX_N=["data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,", "data:audio/wav;base64,"];
const KEYSFX_S=["data:audio/wav;base64,", "data:audio/wav;base64,"];

var KEYSMP_VOL=.85,keyBN=[],keyBS=[],keyLoading=false,keyLast=-1;
function loadKeySfx(){                  // decode sampel keyboard sekali saja
  if(keyLoading||!actx)return;keyLoading=true;
  const dec=(src,arr)=>{try{
    const bin=atob(src.split(",")[1]),u=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
    actx.decodeAudioData(u.buffer,b=>{arr.push(b)},()=>{});
  }catch(e){}};
  KEYSFX_N.forEach(x=>dec(x,keyBN));KEYSFX_S.forEach(x=>dec(x,keyBS));
}
function keyClick(ch){                  // pakai sampel dari video referensi; kalau belum siap, pakai suara sintetis
  try{
    if(!actx)return;
    if(!keyLoading)loadKeySfx();
    const sp=ch===" ",pool=(sp&&keyBS.length)?keyBS:keyBN;
    if(!pool.length){keyClickSynth(ch);return}
    let i=Math.floor(Math.random()*pool.length);
    if(pool.length>1&&i===keyLast)i=(i+1)%pool.length;
    keyLast=i;
    const src=actx.createBufferSource(),g=actx.createGain();
    src.buffer=pool[i];src.playbackRate.value=.95+Math.random()*.1;
    g.gain.value=KEYSMP_VOL*(.8+Math.random()*.25);
    src.connect(g);g.connect(actx.destination);src.start();
  }catch(e){}
}
function keyClickSynth(ch){            // satu "tak" keyboard per huruf; spasi lebih berat
  try{
    if(!actx)return;
    const t=actx.currentTime,sp=ch===" ",v=KEY_VOL*(.8+Math.random()*.4);
    if(!kbNoise)kbNoise=noiseBuf(.06);
    const n=actx.createBufferSource(),f=actx.createBiquadFilter(),g=actx.createGain();
    n.buffer=kbNoise;f.type="bandpass";f.frequency.value=(sp?1300:2500)+Math.random()*900;f.Q.value=.9;
    g.gain.setValueAtTime(v*(sp?.9:.7),t);g.gain.exponentialRampToValueAtTime(.001,t+.045);
    n.connect(f);f.connect(g);g.connect(actx.destination);n.start(t);
    const o=actx.createOscillator(),og=actx.createGain();
    o.type="sine";o.frequency.setValueAtTime(sp?140:210,t);o.frequency.exponentialRampToValueAtTime(sp?60:90,t+.06);
    og.gain.setValueAtTime(v*.55,t);og.gain.exponentialRampToValueAtTime(.001,t+.07);
    o.connect(og);og.connect(actx.destination);o.start(t);o.stop(t+.08);
  }catch(e){}
}
var PROLOGUE=[],PROLOGUE_BTN="Next",PROLOGUE_LAST="Mulai",TYPE_MS=34;
function endDisclaimer(box){
  if(!PROLOGUE.length){wake();return}
  box.style.transition="opacity .9s ease";box.style.opacity=0;     // disclaimer memudar ke layar hitam
  setTimeout(showPrologue,1700);
}
function showPrologue(){
  sleepEl.classList.add("pro");sleepEl.innerHTML="";
  const box=document.createElement("div");box.className="pro-box";sleepEl.appendChild(box);
  let i=0;
  const next=()=>{
    if(i>=PROLOGUE.length){box.style.transition="opacity .9s ease";box.style.opacity=0;setTimeout(()=>{sleepEl.classList.remove("pro");wake()},1300);return}  // fade out -> fade in ke HP
    const txt=PROLOGUE[i],last=i===PROLOGUE.length-1;i++;
    box.style.transition="none";box.style.opacity=1;
    box.innerHTML='<p class="pro-p typing"><span class="typed"></span><span class="rest"></span></p><button class="pro-btn"></button>';
    const typed=box.querySelector(".typed"),rest=box.querySelector(".rest"),p=box.firstChild,btn=box.lastChild;
    btn.textContent=last?PROLOGUE_LAST:PROLOGUE_BTN;btn.style.pointerEvents="none";
    rest.textContent=txt;
    let k=0,done=false,timer;
    const finish=()=>{
      if(done)return;done=true;clearTimeout(timer);
      typed.textContent=txt;rest.textContent="";p.classList.remove("typing");
      setTimeout(()=>{btn.classList.add("on");btn.style.pointerEvents=""},350);
    };
    const tick=()=>{
      k++;typed.textContent=txt.slice(0,k);rest.textContent=txt.slice(k);
      keyClick(txt[k-1]);
      if(k>=txt.length){finish();return}
      timer=setTimeout(tick,TYPE_MS*(.8+Math.random()*.4)+(/[.,:;?!]/.test(txt[k-1])?300:0));
    };
    p.addEventListener("pointerdown",finish);                       // ketuk teks = langsung tampil semua
    btn.addEventListener("click",()=>{btn.style.pointerEvents="none";if(last)stopBacksound();box.style.transition="opacity .8s ease";box.style.opacity=0;setTimeout(next,1000)},{once:true});
    timer=setTimeout(tick,500);
  };
  next();
}
let discShown=false;
function showDisclaimer(){
  if(discShown)return;discShown=true;
  if(BACKSOUND)startBacksound();else{try{startBgm()}catch(e){}}
  sleepEl.classList.remove("intro");
  if(!DISCLAIMER.length&&!DISCLAIMER_TITLE){wake();return}
  // Layar disclaimer: teks muncul perlahan satu per satu, lalu tombol Lanjutkan
  sleepEl.classList.add("disc");sleepEl.innerHTML="";
  const box=document.createElement("div");box.className="disc-box";
  let t=.6;const add=(el,gap)=>{el.style.animationDelay=t+"s";box.appendChild(el);t+=gap};
  if(DISCLAIMER_TITLE){const h=document.createElement("h2");h.textContent=DISCLAIMER_TITLE;add(h,2.8)}
  DISCLAIMER.forEach(x=>{const p=document.createElement("p");p.textContent=x;add(p,Math.max(2.2,x.length/40))});
  const btn=document.createElement("button");btn.textContent=DISCLAIMER_BTN;btn.className="disc-btn";add(btn,0);
  btn.style.pointerEvents="none";setTimeout(()=>{btn.style.pointerEvents=""},t*1000+900);
  btn.addEventListener("click",()=>{btn.disabled=true;endDisclaimer(box)},{once:true});
  sleepEl.appendChild(box);
}
sleepEl.addEventListener("pointerdown",()=>{
  try{if(!actx)actx=new (window.AudioContext||window.webkitAudioContext)();actx.resume();loadSfx();loadKeySfx()}catch(e){}
  if(introImgs.length)playIntro();else showDisclaimer();
},{once:true});

// ===== Spam notifikasi Kontak (banner) — berhenti setelah "bales dong" =====
const sp={i:0,stop:false};
