var SPAM=[];
async function spam(){
  sp.stop=true;const d=document.querySelector(".bn");if(d)d.remove();
  await wait(300);
  for(let j=0;j<SPAM.length;j++){if(j>=sp.i){await wait(420+Math.random()*250);if(navigator.vibrate)navigator.vibrate(30)}bub(SPAM[j],false)}
  await wait(1100);if(REPLY_AFTER_SPAM)bub(REPLY_AFTER_SPAM,true);await wait(900);
}
