// ===== Jam & tanggal mengikuti HP pengguna =====
function startClock(){
  const H=["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"],B=["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];
  const p=n=>String(n).padStart(2,"0");
  const tick=()=>{const d=new Date();
    lock.querySelector(".date").textContent=H[d.getDay()]+", "+d.getDate()+" "+B[d.getMonth()];
    lock.querySelector(".time").textContent=p(d.getHours())+":"+p(d.getMinutes());
    const st=document.querySelector(".status span");if(st)st.textContent=d.getHours()+":"+p(d.getMinutes());};
  tick();setInterval(tick,5000);
}
// ===== Petunjuk kode sandi: teka-teki + petunjuk tersebar di layar kunci =====
var CODE_RIDDLE="",CODE_CLUES=[];
const foundClue={};let tapX=0,tapY=0;
// Kalau CODE_CLUES diisi, kode dihitung dari petunjuk (bisa berbeda tiap pengguna/waktu).
function currentCode(){
  if(!CODE_CLUES.length)return CODE;
  return CODE_CLUES.map((c,i)=>foundClue[i]?foundClue[i].value:String(c.value())).join("");
}
function clueEl(at){
  const q=lock.querySelectorAll(".q"),sv=document.querySelectorAll(".status .r svg");
  return {date:lock.querySelector(".date"),time:lock.querySelector(".time"),flashlight:q[0],camera:q[1],battery:sv[2],signal:sv[0],wifi:sv[1],island:$("island")}[at];
}
function showClue(i){
  const cl=CODE_CLUES[i];
  if(!foundClue[i])foundClue[i]={text:typeof cl.text==="function"?cl.text():cl.text,value:String(cl.value())};
  let t=document.querySelector(".cluetoast");if(t)t.remove();
  t=document.createElement("div");t.className="cluetoast";
  t.innerHTML="<b>Petunjuk angka "+(i+1)+"</b>"+foundClue[i].text.replace(/\n/g,"<br>");
  phone.appendChild(t);
  try{ping()}catch(e){}if(navigator.vibrate)navigator.vibrate(40);
  setTimeout(()=>t.remove(),6000);
}
phone.addEventListener("pointerdown",e=>{tapX=e.clientX;tapY=e.clientY},true);
phone.addEventListener("pointerup",e=>{
  if(lock.classList.contains("gone")||Math.hypot(e.clientX-tapX,e.clientY-tapY)>8)return;
  let best=-1,bd=13;
  CODE_CLUES.forEach((cl,i)=>{
    const el=clueEl(cl.at);if(!el)return;const r=el.getBoundingClientRect();
    const dx=Math.max(r.left-e.clientX,0,e.clientX-r.right),dy=Math.max(r.top-e.clientY,0,e.clientY-r.bottom),d=Math.hypot(dx,dy);
    if(d<bd){bd=d;best=i}
  });
  if(best>=0)showClue(best);
},true);
function setupHint(){
  const hb=$("hintbtn"),bx=$("hintbox");
  hb.hidden=!CODE_RIDDLE;
  hb.onclick=()=>{
    const ct=document.querySelector(".cluetoast");if(ct)ct.remove();
    let t=CODE_RIDDLE;
    if(CODE_CLUES.length){
      t+="\n\nPetunjuk yang sudah kamu temukan:";
      CODE_CLUES.forEach((cl,i)=>{t+="\n\nPetunjuk angka "+(i+1)+": "+(foundClue[i]?foundClue[i].text:"belum ketemu")});
      t+="\n\nSusunan kode: [Angka 1] [Angka 2] [Angka 3] [Angka 4]";
    }
    $("hinttxt").textContent=t;bx.hidden=false;
  };
  $("hintx").onclick=()=>{bx.hidden=true};
}

// ===== Layar penuh: tombol kecil + ketuk 2x di area kosong =====
(function(){
  const de=document.documentElement;
  const canFS=!!(de.requestFullscreen||de.webkitRequestFullscreen);
  const isFS=()=>!!(document.fullscreenElement||document.webkitFullscreenElement);
  const ICON_IN='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>';
  const ICON_OUT='<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5"/></svg>';
  const btn=document.createElement("button");btn.className="fsbtn";btn.setAttribute("aria-label","Layar penuh");
  const sync=()=>{btn.innerHTML=isFS()?ICON_OUT:ICON_IN};sync();
  function note(t){
    let n=document.querySelector(".fsnote");if(n)n.remove();
    n=document.createElement("div");n.className="fsnote";n.textContent=t;phone.appendChild(n);setTimeout(()=>n.remove(),3500);
  }
  function toggleFS(){
    try{
      if(isFS()){(document.exitFullscreen||document.webkitExitFullscreen).call(document);return}
      if(!canFS){note("Layar penuh tidak didukung di browser ini.");return}
      const p=(de.requestFullscreen||de.webkitRequestFullscreen).call(de);
      if(p&&p.catch)p.catch(()=>note("Layar penuh diblokir di halaman ini. Coba buka di tab browser sendiri."));
    }catch(e){note("Layar penuh tidak tersedia di sini.")}
  }
  document.addEventListener("fullscreenchange",sync);document.addEventListener("webkitfullscreenchange",sync);
  btn.addEventListener("pointerdown",e=>{e.preventDefault();e.stopPropagation();toggleFS()});
  btn.addEventListener("click",e=>{if(e.detail===0)toggleFS()});
  phone.appendChild(btn);
  // ketuk 2x: hanya di area kosong (bukan tombol, keypad, ikon, teks yang bisa diketuk)
  const SKIP="button,input,a,.k,.app,.q,.date,.time,.status,#island,.hintbox,.cluetoast,.pro-p,.m,.c,.fsbtn";
  let lt=0,lx=0,ly=0;
  document.addEventListener("pointerup",e=>{
    if(e.target.closest&&e.target.closest(SKIP)){lt=0;return}
    const now=performance.now();
    if(now-lt<330&&Math.hypot(e.clientX-lx,e.clientY-ly)<45){lt=0;toggleFS()}
    else{lt=now;lx=e.clientX;ly=e.clientY}
  },true);
})();
